  'старый':{ ru:'ста́рый', vi:'cũ, già', pos:'tính từ', senses:[{vi:'già (người)', ex:['Ста́рый челове́к.','Người già.']},{vi:'cũ (đồ vật)', ex:['Ста́рая маши́на.','Xe cũ.']}], note:'So sánh: ста́рше (tuổi), старе́е (đồ); dạng ngắn стар, стара́.' },
  'красивый':{ ru:'краси́вый', vi:'đẹp', pos:'tính từ', senses:[{vi:'đẹp', ex:['Краси́вый го́род.','Thành phố đẹp.']}], note:'Dạng ngắn краси́в, краси́ва; so sánh краси́вее. Đẹp trai/gái: краса́вец / краса́вица.' },
  'молодой':{ ru:'молодо́й', vi:'trẻ', pos:'tính từ', senses:[{vi:'trẻ tuổi', ex:['Молодо́й челове́к!','Này anh bạn trẻ!']},{vi:'non, mới (rượu, khoai)', ex:['молодо́е вино́','rượu mới']}], note:'So sánh моло́же; dạng ngắn мо́лод, молода́, мо́лоды.' },
