  'русский':{ ru:'ру́сский', vi:'Nga (dân tộc, ngôn ngữ)', pos:'tính từ / danh từ', senses:[{vi:'thuộc về người Nga', ex:['ру́сский язы́к, ру́сская литерату́ра','tiếng Nga, văn học Nga']},{vi:'người Nga (danh từ hoá)', ex:['Он ру́сский, она́ ру́сская.','Anh ấy là người Nga, cô ấy là người Nga.']}], note:'ру́сский (dân tộc) ≠ росси́йский (thuộc Liên bang Nga, quốc tịch): росси́йский па́спорт, but ру́сский язы́к.' },
