  'с':{ ru:'с (со)', vi:'với; từ', pos:'giới từ', senses:[{vi:'+ cách 5: cùng với', ex:['Я иду́ с дру́гом.','Tôi đi với bạn.']},{vi:'+ cách 2: từ (bề mặt, nơi «на»), từ khi', ex:['с рабо́ты, с утра́, с 2020 го́да','từ chỗ làm, từ sáng, từ năm 2020']}], coll:['с удово́льствием — rất sẵn lòng','с днём рожде́ния — chúc mừng sinh nhật','с тех пор — từ đó'], note:'Cặp: на → с (на по́чту → с по́чты); в → из.' },
