  'о':{ ru:'о (об, обо)', vi:'về', pos:'giới từ (+ cách 6)', senses:[{vi:'nói/nghĩ về', ex:['Мы говори́м о Росси́и.','Chúng tôi nói về nước Nga.']}], note:'об trước nguyên âm: об э́том, об университе́те; обо мне, обо всём.' },
