  'от':{ ru:'от (ото)', vi:'từ (người, nguồn); vì', pos:'giới từ (+ cách 2)', senses:[{vi:'từ ai', ex:['письмо́ от дру́га','thư từ bạn']},{vi:'vì (nguyên nhân)', ex:['пла́кать от ра́дости','khóc vì vui']},{vi:'cách xa', ex:['недалеко́ от це́нтра','không xa trung tâm']}], note:'Cặp к → от.' },
