  'уже':{ ru:'уже́', vi:'đã, rồi', pos:'trạng từ', senses:[{vi:'đã (xong, sớm hơn mong đợi)', ex:['Он уже́ пришёл.','Anh ấy đã đến rồi.']}], note:'Đối lập ещё (vẫn, còn): Он ещё не пришёл.' },
