  'очень':{ ru:'о́чень', vi:'rất', pos:'trạng từ', senses:[{vi:'rất', ex:['О́чень прия́тно!','Rất hân hạnh!']}], note:'Không dùng với động từ chỉ hành động: о́чень люблю́ ✓, о́чень рабо́таю ✗ (мно́го рабо́таю).' },
  'только':{ ru:'то́лько', vi:'chỉ; vừa mới', pos:'tiểu từ / trạng từ', senses:[{vi:'chỉ', ex:['То́лько ты зна́ешь.','Chỉ cậu biết.']},{vi:'vừa mới', ex:['Он то́лько пришёл.','Anh ấy vừa đến.']},{vi:'как то́лько — ngay khi', ex:['Позвони́, как то́лько прие́дешь.','Gọi ngay khi đến nhé.']}], coll:['то́лько что — vừa mới','не то́лько…, но и… — không chỉ… mà còn','то́лько и всего́ — chỉ thế thôi'] },
